import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0001: 为什么选择 Rust","description":"","frontmatter":{},"headers":[],"relativePath":"zh/adr/ADR-0001-why-rust.md","filePath":"zh/adr/ADR-0001-why-rust.md","lastUpdated":0}`),a={name:`zh/adr/ADR-0001-why-rust.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0001-为什么选择-rust" tabindex="-1">ADR-0001: 为什么选择 Rust <a class="header-anchor" href="#adr-0001-为什么选择-rust" aria-label="Permalink to “ADR-0001: 为什么选择 Rust”">​</a></h1><ul><li>状态：已接受</li><li>日期：2026-10-31</li><li>关联：docs/guide/overview.md，workspace.md</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>Custos 是常驻本地的自愈引擎：长期运行、低抖动要求高、必须跨平台（Linux/Windows 优先）、 单二进制部署、领域模型里有严格的状态机（恢复运行、健康转换、预算与互斥）。选型决定了 内存安全、部署形态和长期维护成本。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to “决策”">​</a></h2><p>选择 Rust 作为唯一实现语言：领域模型用类型编码（<code>HealthStatus</code> 七态、<code>RecoveryRunStatus</code> 状态机、强类型 ID），workspace 按 crate 分层（model/engine/probe/notify/store/config/cli）， 异步仅在 store 内部（sync 门面 + current-thread runtime），TLS 用 rustls 保持纯 Rust 可交叉编译。</p><h2 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to “替代方案”">​</a></h2><ul><li><strong>Go</strong>：GC 停顿与常驻内存占用更高；错误处理靠约定（err != nil）无编译期约束； 交叉编译单二进制可行但状态机正确性靠人。</li><li><strong>C/C++</strong>：内存安全不可接受——自愈引擎拥有系统级权限，UAF/溢出即权限提升。</li><li><strong>Python/脚本</strong>：性能与部署（解释器、依赖树）不适合常驻引擎；类型约束弱。</li></ul><h2 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to “优缺点”">​</a></h2><p>优点：无 GC 的可预测延迟；<code>enum + match</code> 穷尽性检查让状态机漏分支编译期报错； crates.io 成熟生态（rustls/sqlx/lettre/ureq）符合&quot;核心用成熟库&quot;的裁定； 单二进制、交叉编译到 mingw 验证过。 缺点：编译时间长；开发迭代慢于脚本语言；部分生态（PyO3 出向绑定）有额外复杂度。</p><h2 id="后续影响" tabindex="-1">后续影响 <a class="header-anchor" href="#后续影响" aria-label="Permalink to “后续影响”">​</a></h2><ul><li>workspace 11 个 crate 的分层由 Rust 模块系统承载（依赖方向单向）。</li><li>所有&quot;核心用成熟 crate、插件侧轻依赖&quot;的裁定以此为基础。</li><li>rust-toolchain.toml 需声明 stable 通道（todo.md 工程修缮项）。</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};